import type { ComponentProps } from 'react';
import { BLOG_IMAGES } from '../../lib/images.generated';

interface BlogImgProps extends Omit<
  ComponentProps<'img'>,
  'src' | 'srcSet' | 'width' | 'height' | 'alt'
> {
  /** Image id in BLOG_IMAGES. */
  image: string | null;
  sizes: string;
  alt?: string;
  priority?: boolean;
}

/** Responsive image for imported blog covers/inline images (manifest generated by `npm run images`). */
export function BlogImg({ image, sizes, alt = '', priority, ...rest }: BlogImgProps) {
  const meta = image ? BLOG_IMAGES[image] : undefined;
  if (!image || !meta) return <div aria-hidden="true" className={rest.className} />;
  const last = meta.widths[meta.widths.length - 1];
  return (
    <img
      src={`/blog/${image}-${last}.webp`}
      srcSet={meta.widths.map((w) => `/blog/${image}-${w}.webp ${w}w`).join(', ')}
      sizes={sizes}
      width={meta.width}
      height={meta.height}
      alt={alt}
      loading={priority ? 'eager' : 'lazy'}
      fetchPriority={priority ? 'high' : undefined}
      decoding="async"
      {...rest}
    />
  );
}
